#include <Arduino.h>
#include <SPI.h>
#include <SD.h>
#include <ESP8266Audio.h>
#include <config.h>

// === Настройка пинов SD-карты ===
#define SD_CS_PIN   5    // D5
#define SD_SCK_PIN  18   // D18
#define SD_MOSI_PIN 23   // D23
#define SD_MISO_PIN 19   // D19

// === MAC-адрес ваших наушников ===
esp_bd_addr_t target_mac = {0x41, 0x42, 0x82, 0xB4, 0x70, 0x09};

BluetoothA2DPSource a2dp_source;
AudioGeneratorMP3 *mp3;
AudioFileSourceSD *file;

// Очередь для передачи аудиоданных между декодером и Bluetooth
QueueHandle_t audioQueue;

// === Плейлист ===
String playlist[50];
int trackCount = 0;
int currentTrackIndex = 0;
bool isPlaying = false;
bool trackChanged = false;

// === Класс-мост (принимает звук от ESP8266Audio и кладет в очередь) ===
class AudioOutputQueue : public AudioOutput {
  public:
      bool ConsumeSample(int16_t sample[2]) override {
              // Кладем левый и правый канал в очередь
                      if (xQueueSend(audioQueue, &sample[0], 0) != pdPASS) return false;
                              if (xQueueSend(audioQueue, &sample[1], 0) != pdPASS) return false;
                                      return true;
                                          }
                                              bool SetRate(int hz) override { return true; }
                                                  bool SetChannels(int ch) override { return true; }
                                                      bool begin() override { return true; }
                                                          bool stop() override { return true; }
                                                          };
                                                          AudioOutputQueue *out;

                                                          // === Функция, которую вызывает Bluetooth для получения звука ===
                                                          int32_t get_sound_data(uint8_t *data, int32_t len) {
                                                              int16_t *ptr = (int16_t*)data;
                                                                  int32_t samplesNeeded = len / 2;
                                                                      for (int i = 0; i < samplesNeeded; i++) {
                                                                              int16_t sample = 0;
                                                                                      // Если играет - берем из очереди, если пауза - отправляем тишину (0)
                                                                                              if (isPlaying) {
                                                                                                          xQueueReceive(audioQueue, &sample, 0);
                                                                                                                  }
                                                                                                                          ptr[i] = sample;
                                                                                                                              }
                                                                                                                                  return len;
                                                                                                                                  }

                                                                                                                                  // === Обработка кнопок на наушниках (AVRCP) ===
                                                                                                                                  void avrc_control_callback(uint8_t id, bool isReleased) {
                                                                                                                                      if (!isReleased) return;
                                                                                                                                          switch (id) {
                                                                                                                                                  case 0x44: // Play
                                                                                                                                                              isPlaying = true;
                                                                                                                                                                          Serial.println("Играть");
                                                                                                                                                                                      break;
                                                                                                                                                                                              case 0x45: // Pause
                                                                                                                                                                                                          isPlaying = false;
                                                                                                                                                                                                                      xQueueReset(audioQueue); // очищаем буфер при паузе
                                                                                                                                                                                                                                  Serial.println("Пауза");
                                                                                                                                                                                                                                              break;
                                                                                                                                                                                                                                                      case 0x46: // Play/Pause toggle
                                                                                                                                                                                                                                                                  isPlaying = !isPlaying;
                                                                                                                                                                                                                                                                              if (!isPlaying) xQueueReset(audioQueue);
                                                                                                                                                                                                                                                                                          Serial.println(isPlaying ? "Играть" : "Пауза");
                                                                                                                                                                                                                                                                                                      break;
                                                                                                                                                                                                                                                                                                              case 0x4B: // Next
                                                                                                                                                                                                                                                                                                                          currentTrackIndex = (currentTrackIndex + 1) % trackCount;
                                                                                                                                                                                                                                                                                                                                      trackChanged = true; isPlaying = true;
                                                                                                                                                                                                                                                                                                                                                  Serial.println("Следующий трек");
                                                                                                                                                                                                                                                                                                                                                              break;
                                                                                                                                                                                                                                                                                                                                                                      case 0x4C: // Previous
                                                                                                                                                                                                                                                                                                                                                                                  currentTrackIndex = (currentTrackIndex - 1 + trackCount) % trackCount;
                                                                                                                                                                                                                                                                                                                                                                                              trackChanged = true; isPlaying = true;
                                                                                                                                                                                                                                                                                                                                                                                                          Serial.println("Предыдущий трек");
                                                                                                                                                                                                                                                                                                                                                                                                                      break;
                                                                                                                                                                                                                                                                                                                                                                                                                              default:
                                                                                                                                                                                                                                                                                                                                                                                                                                          Serial.printf("Нажата кнопка ID: 0x%02X\n", id);
                                                                                                                                                                                                                                                                                                                                                                                                                                                      break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                          // === Автопоиск музыки ===
                                                                                                                                                                                                                                                                                                                                                                                                                                                          void scanMusic() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                              trackCount = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  File root = SD.open("/");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (!root) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          File entry = root.openNextFile();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              while (entry) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (!entry.isDirectory()) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  String name = entry.name();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              name.toLowerCase();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (name.endsWith(".mp3") && trackCount < 50) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          playlist[trackCount] = String("/") + entry.name();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          trackCount++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      entry = root.openNextFile();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              root.close();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Serial.printf("Найдено треков на SD: %d\n", trackCount);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  void setup() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      Serial.begin(115200);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // 1. Инициализация SD-карты
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              SPI.begin(SD_SCK_PIN, SD_MISO_PIN, SD_MOSI_PIN, SD_CS_PIN);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (!SD.begin(SD_CS_PIN)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Serial.println("SD Card Mount Failed");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  while(1); // Остановка, если карта не найдена
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              scanMusic();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (trackCount == 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Serial.println("Файлы MP3 не найдены!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  while(1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // 2. Создаем очередь на 20000 сэмплов (около 40 КБ памяти)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              audioQueue = xQueueCreate(20000, sizeof(int16_t));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // 3. Инициализация аудио-объектов
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      mp3 = new AudioGeneratorMP3();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          file = new AudioFileSourceSD();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              out = new AudioOutputQueue();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // 4. Настройка Bluetooth
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      a2dp_source.set_avrc_passthru_command_callback(avrc_control_callback);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          a2dp_source.connect_to(target_mac); // Подключение по MAC-адресу
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              a2dp_source.start("ESP32_Player", get_sound_data);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // 5. Запуск первого трека
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      currentTrackIndex = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          trackChanged = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              isPlaying = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              void loop() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // Если трек был сменен вручную с наушников
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (trackChanged) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              mp3->stop();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (file->isOpen()) file->close();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Serial.printf("Играет: %s\n", playlist[currentTrackIndex].c_str());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (file->open(playlist[currentTrackIndex].c_str())) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  mp3->begin(file, out);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  trackChanged = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // Декодируем звук (только если не на паузе)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (isPlaying && mp3->isRunning()) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (!mp3->loop()) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // Трек закончился - переходим к следующему
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              currentTrackIndex = (currentTrackIndex + 1) % trackCount;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          trackChanged = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          delay(1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
